def median(xs):
    sorted_xs = sorted(xs)
    if not sorted_xs:
        raise ValueError("Cannot compute median of empty list")

    n = len(sorted_xs)
    if n % 2 == 1:
        return sorted_xs[n // 2]
    else:
        return (sorted_xs[n // 2 - 1] + sorted_xs[n // 2]) / 2
